export function cartLinesDiscountsGenerateRun(input) {
  const totalQty = input.cart.lines.reduce((sum, l) => sum + l.quantity, 0);
  if (totalQty < 3) return { operations: [] };

  return {
    operations: [{
      orderDiscountsAdd: {
        selectionStrategy: "FIRST",
        candidates: [{
          message: "10% OFF acima de 3 itens",
          targets: [{ orderSubtotal: { excludedCartLineIds: [] } }],
          value: { percentage: { value: "10.0" } }
        }]
      }
    }]
  };
}

export function cartLinesDiscountsGenerateRun(input) {
  const totalQty = input.cart.lines.reduce((sum, l) => sum + l.quantity, 0);
  let percent = 0;
  if (totalQty >= 10) percent = 15;
  else if (totalQty >= 6) percent = 10;
  else if (totalQty >= 3) percent = 5;

  if (percent === 0) return { operations: [] };

  return {
    operations: [{
      orderDiscountsAdd: {
        selectionStrategy: "FIRST",
        candidates: [{
          message: `${percent}% OFF por volume`,
          targets: [{ orderSubtotal: { excludedCartLineIds: [] } }],
          value: { percentage: { value: String(percent) } }
        }]
      }
    }]
  };
}
